"""Tests for the safe summary generated by the real Ollama test runner."""

import json

from scripts.ollama_test_report import build_summary


def test_summary_counts_junit_results_and_never_copies_failure_output(tmp_path):
    junit = tmp_path / "junit.xml"
    output = tmp_path / "run"
    junit.write_text(
        """<?xml version="1.0" encoding="utf-8"?>
<testsuites tests="3" failures="1" errors="0" skipped="1" time="4.5">
  <testsuite name="live" tests="3" failures="1" errors="0" skipped="1" time="4.5">
    <properties>
      <property name="language_understanding_model" value="gemma4:26b"/>
      <property name="language_understanding_provider_calls" value="12"/>
      <property name="discourse_holdout_prompt_observations" value="DO_NOT_COPY_ME"/>
    </properties>
    <testcase classname="tests.live" name="test_passed" time="1.0"/>
    <testcase classname="tests.live" name="test_failed" time="2.0">
      <failure message="DO_NOT_COPY_ME">PLAYER_SECRET_UTTERANCE</failure>
      <system-out>PRIVATE_PROMPT_TEXT</system-out>
    </testcase>
    <testcase classname="tests.live" name="test_skipped" time="1.5">
      <skipped/>
    </testcase>
  </testsuite>
</testsuites>
""",
        encoding="utf-8",
    )
    (output / "reports").mkdir(parents=True)
    (output / "reports" / "semantic.json").write_text(
        json.dumps({
            "schema_version": 1,
            "evaluation": "language",
            "corpus": "language_holdout_v1",
            "metadata": {
                "model": "gemma4:26b",
                "provider_calls": 12,
                "elapsed_seconds": 4.5,
                "player_input": "PRIVATE_PROMPT_TEXT",
            },
            "metrics": {
                "entity_link_precision": 0.9,
                "entity_link_recall": 0.8,
                "untrusted_text": "PLAYER_SECRET_UTTERANCE",
            },
            "provider_usage": [{
                "provider_model": "gemma4:26b",
                "duration_ms": 450,
                "prompt": "PRIVATE_PROMPT_TEXT",
            }],
        }),
        encoding="utf-8",
    )

    summary = build_summary(
        junit_xml=junit,
        output_dir=output,
        commit="a" * 40,
    )

    assert summary["status"] == "failed"
    assert summary["pytest"]["tests"] == 3
    assert summary["pytest"]["failures"] == 1
    assert summary["pytest"]["errors"] == 0
    assert summary["pytest"]["skipped"] == 1
    assert summary["pytest"]["duration_seconds"] == 4.5
    assert summary["pytest"]["failed_tests"] == ["tests.live::test_failed"]
    assert summary["pytest"]["safe_properties"] == {
        "language_understanding_model": "gemma4:26b",
        "language_understanding_provider_calls": 12,
    }

    serialized = (output / "summary.json").read_text(encoding="utf-8")
    markdown = (output / "summary.md").read_text(encoding="utf-8")
    assert "DO_NOT_COPY_ME" not in serialized
    assert "PLAYER_SECRET_UTTERANCE" not in serialized
    assert "PRIVATE_PROMPT_TEXT" not in serialized
    assert "DO_NOT_COPY_ME" not in markdown
    assert "PRIVATE_PROMPT_TEXT" not in markdown
    assert summary["live_reports"][0]["metrics"] == {
        "entity_link_precision": 0.9,
        "entity_link_recall": 0.8,
    }
    assert summary["live_reports"][0]["provider_usage"] == [{
        "provider_model": "gemma4:26b",
        "duration_ms": 450,
    }]


def test_summary_is_created_when_pytest_did_not_produce_junit(tmp_path):
    summary = build_summary(
        junit_xml=tmp_path / "missing.xml",
        output_dir=tmp_path / "run",
        commit=None,
    )

    assert summary["status"] == "not_run"
    assert summary["pytest"]["junit_available"] is False
    assert summary["pytest"]["tests"] == 0
    markdown = (tmp_path / "run" / "summary.md").read_text(encoding="utf-8")
    assert "JUnit XML was not produced" in markdown



def test_summary_keeps_only_allowlisted_semantic_family_metrics_from_junit(tmp_path):
    junit = tmp_path / "metrics.xml"
    output = tmp_path / "run"
    junit.write_text(
        """<testsuites>
  <testsuite>
    <properties>
      <property name="semantic_holdout_intent_action_attempt_case_accuracy" value="0.8333"/>
      <property name="semantic_holdout_intent_action_attempt_slot_recall" value="0.75"/>
      <property name="semantic_holdout_intent_action_frame_semantic_slots_precision" value="0.91"/>
      <property name="semantic_holdout_intent_action_frame_semantic_slots_f1" value="0.88"/>
      <property name="semantic_holdout_intent_action_attempt_mean_latency_seconds" value="1.25"/>
      <property name="semantic_holdout_intent_entity_link_precision" value="0.9"/>
      <property name="semantic_holdout_intent_prompt_observations" value="PRIVATE_TEXT"/>
      <property name="semantic_holdout_intent_provider_usage" value='{"calls":3,"prompt_tokens_total":120,"unsafe":"PRIVATE_TEXT"}'/>
    </properties>
    <testcase classname="tests.live" name="test_ok" time="1.0"/>
  </testsuite>
</testsuites>
""",
        encoding="utf-8",
    )

    summary = build_summary(junit_xml=junit, output_dir=output)
    properties = summary["pytest"]["safe_properties"]
    assert properties["semantic_holdout_intent_action_attempt_case_accuracy"] == 0.8333
    assert properties["semantic_holdout_intent_action_attempt_slot_recall"] == 0.75
    assert properties["semantic_holdout_intent_action_frame_semantic_slots_precision"] == 0.91
    assert properties["semantic_holdout_intent_action_frame_semantic_slots_f1"] == 0.88
    assert properties["semantic_holdout_intent_action_attempt_mean_latency_seconds"] == 1.25
    assert properties["semantic_holdout_intent_entity_link_precision"] == 0.9
    assert properties["semantic_holdout_intent_provider_usage"] == {
        "calls": 3,
        "prompt_tokens_total": 120,
    }
    assert "semantic_holdout_intent_prompt_observations" not in properties


def test_summary_survives_malformed_or_truncated_junit_xml(tmp_path):
    junit = tmp_path / "broken.xml"
    output = tmp_path / "run"
    junit.write_text("<testsuites><testsuite>", encoding="utf-8")

    summary = build_summary(junit_xml=junit, output_dir=output)

    assert summary["status"] == "not_run"
    assert summary["pytest"]["junit_available"] is False
    assert summary["pytest"]["junit_error"] == "missing_or_invalid"
    assert (output / "summary.md").is_file()
    assert (output / "summary.json").is_file()
